#pragma once
namespace merchant {
inline void marketingAutomation(crow::SimpleApp &app){
    {Db d(path);d.exec("CREATE TABLE IF NOT EXISTS marketing_automation(stall_id INTEGER PRIMARY KEY,welcome TEXT NOT NULL,reactivation TEXT NOT NULL,inactive_days INTEGER NOT NULL,paused INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS automatic_marketing_deliveries(office_id INTEGER NOT NULL,kind TEXT NOT NULL,period INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(office_id,kind,period));");}
    CROW_ROUTE(app,"/api/marketing-automation").methods("GET"_method,"POST"_method)([](const crow::request &r){return handle([&]{Db d(path);auto sid=stall(d,owner(d,r));
        if(r.method==crow::HTTPMethod::Post){auto j=body(r);require(flag(j,"approved"),400,"Approve exact templates before enabling automation");auto welcome=optionalText(j,"welcome",1500),reactivation=optionalText(j,"reactivation",1500);auto days=integer(j,"inactive_days",7,365);auto paused=flag(j,"paused");Stmt s(d,"INSERT INTO marketing_automation VALUES(?,?,?,?,?) ON CONFLICT(stall_id) DO UPDATE SET welcome=excluded.welcome,reactivation=excluded.reactivation,inactive_days=excluded.inactive_days,paused=excluded.paused");s.bind(1,sid).bind(2,welcome).bind(3,reactivation).bind(4,days).bind(5,paused?1:0).row();}
        Stmt s(d,"SELECT welcome,reactivation,inactive_days,paused FROM marketing_automation WHERE stall_id=?");s.bind(1,sid);bool exists=s.row();Json out;out["welcome"]=exists?s.str(0):"";out["reactivation"]=exists?s.str(1):"";out["inactive_days"]=exists?s.num(2):30;out["paused"]=!exists||bool(s.num(3));return json(200,std::move(out));
    });});
    CROW_ROUTE(app,"/internal/marketing-candidates")([](const crow::request &r){return handle([&]{internal(r);Db d(path);Stmt s(d,"SELECT o.id,o.stall_id,a.inactive_days FROM offices o JOIN marketing_consent c ON c.office_id=o.id JOIN marketing_controls m ON m.stall_id=o.stall_id JOIN marketing_automation a ON a.stall_id=o.stall_id WHERE o.service_enabled=1 AND c.enabled=1 AND m.paused=0 AND a.paused=0 ORDER BY o.id LIMIT 1000");Json out;out["candidates"]=Json::list();int i=0;while(s.row()){out["candidates"][i]["office_id"]=s.num(0);out["candidates"][i]["stall_id"]=s.num(1);out["candidates"][i++]["inactive_days"]=s.num(2);}return json(200,std::move(out));});});
    CROW_ROUTE(app,"/internal/automatic-marketing").methods("POST"_method)([](const crow::request &r){return handle([&]{internal(r);auto j=body(r);auto sid=integer(j,"stall_id",1,1000000000),oid=integer(j,"office_id",1,1000000000);auto kind=text(j,"kind",20);require(kind=="WELCOME"||kind=="REACTIVATION",400,"Invalid automation kind");auto period=kind=="WELCOME"?0:(now()+19800)/(7*86400);Db d(path);Transaction tx(d);Stmt prior(d,"SELECT 1 FROM automatic_marketing_deliveries WHERE office_id=? AND kind=? AND period=?");prior.bind(1,oid).bind(2,kind).bind(3,period);Json out;out["stored"]=false;
        if(prior.row()){tx.commit();return json(200,std::move(out));}
        Stmt settings(d,"SELECT a.welcome,a.reactivation,m.weekly_cap FROM offices o JOIN marketing_consent c ON c.office_id=o.id JOIN marketing_controls m ON m.stall_id=o.stall_id JOIN marketing_automation a ON a.stall_id=o.stall_id WHERE o.id=? AND o.stall_id=? AND c.enabled=1 AND o.service_enabled=1 AND m.paused=0 AND a.paused=0");settings.bind(1,oid).bind(2,sid);require(settings.row(),409,"Automation paused or office opted out");auto content=settings.str(kind=="WELCOME"?0:1);require(!content.empty(),409,"Automation template not configured");Stmt recent(d,"SELECT COUNT(*) FROM campaign_deliveries WHERE office_id=? AND created>?");recent.bind(1,oid).bind(2,now()-7*86400);recent.row();require(recent.num(0)<settings.num(2),409,"Marketing frequency cap reached");
        auto id=token();Stmt message(d,"INSERT INTO messages(stall_id,office_id,sender,body,idem,created) VALUES(?,?,'OWNER',?,?,?)");message.bind(1,sid).bind(2,oid).bind(3,"Optional stall update: "+content+"\nUnsubscribe from optional updates in your office portal.").bind(4,"auto-"+id).bind(5,now()).row();auto mid=sqlite3_last_insert_rowid(d.p);Stmt delivery(d,"INSERT INTO campaign_deliveries VALUES(?,?,?,?)");delivery.bind(1,id).bind(2,oid).bind(3,mid).bind(4,now()).row();Stmt record(d,"INSERT INTO automatic_marketing_deliveries VALUES(?,?,?,?)");record.bind(1,oid).bind(2,kind).bind(3,period).bind(4,now()).row();audit(d,"AUTOMATIC_MARKETING",std::to_string(oid),"worker",kind);tx.commit();out["stored"]=true;return json(200,std::move(out));
    });});
}
}
